.ds-button-primary { font-family: var(--body, Public,sans-serif); border: 0; cursor: pointer; transition: background .18s, color .18s; color: var(--ink, #253b30); }
.ds-button-primary {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 24px;
  min-height: 52px;
  padding: 15px 24px;
  text-decoration: none;
  font-size: 14px;
  font-weight: 600;
  border-radius: 4px;
  white-space: nowrap;
}
.ds-button-primary {
  background: var(--pine, #234b39);
  color: var(--white, #fffefa);
}
.ds-button-primary:hover {
  background: #143825;
}
.ds-button-primary:focus-visible { outline: 3px solid var(--pine, #234b39); outline-offset: 5px; }
