.ds-field { font-family: var(--body, Public,sans-serif); color: var(--ink, #253b30); }
.ds-field label {
  display: block;
  font-size: 12px;
  font-weight: 600;
  margin-bottom: 6px;
}
.ds-field input {
  width: 100%;
  min-height: 46px;
  border: 1px solid #a5b49e;
  background: var(--white, #fffefa);
  border-radius: 4px;
  padding: 10px;
  font-size: 13px;
}
.ds-field input { font-family: var(--body, Public,sans-serif); color: var(--ink, #253b30); min-width: 0; caret-color: var(--pine, #234b39); }
.ds-field input:focus-visible { outline: 3px solid var(--pine, #234b39); outline-offset: 5px; }

.ds-masthead { font-family: var(--body, Public,sans-serif); }
.ds-masthead {
  background: var(--pine, #234b39);
  color: var(--white, #fffefa);
  display: flex;
  align-items: center;
  gap: 40px;
  min-height: 98px;
  padding: 20px var(--space, clamp(24px,5vw,80px));
}
.ds-masthead {
    padding: 18px 24px 12px;
    flex-wrap: wrap;
    min-height: 0;
    justify-content: space-between;
    gap: 16px;
  }
.ds-wordmark {
  font-family: var(--display, Archivo,sans-serif);
  font-size: 39px;
  letter-spacing: -.04em;
  text-decoration: none;
  display: inline-flex;
  align-items: center;
  gap: 2px;
  line-height: 1;
}
.ds-wordmark {
    font-size: 34px;
  }
.ds-wordmark svg {
    width: 24px;
    height: 24px;
  }
.ds-wordmark { color: inherit; }
.ds-nav {
  display: flex;
  gap: 28px;
  margin: auto;
  font-size: 13px;
  font-weight: 500;
}
.ds-nav {
    order: 3;
    width: 100%;
    justify-content: space-between;
    gap: 4px;
    font-size: 12px;
  }
.ds-nav a { color: inherit; }
.ds-nav a {
  text-decoration: none;
  display: flex;
  align-items: center;
  min-height: 44px;
  padding: 10px 14px;
  border-radius: 8px;
  transition: background .2s ease, color .2s ease, transform .2s var(--ease, cubic-bezier(.16,1,.3,1));
}
.ds-nav a {
    min-height: 38px;
    padding: 8px 4px;
  }
.ds-nav a:hover {
  background: #385d48;
  color: var(--lime, #e5ed83);
  transform: translateY(-1px);
}
.ds-nav a:active {
  transform: translateY(0);
}
.ds-masthead :focus-visible { outline: 3px solid var(--lime, #e5ed83); outline-offset: 5px; }
.ds-header-plan { font-family: var(--body, Public,sans-serif); border: 0; cursor: pointer; }
.ds-header-plan {
  display: inline-flex;
  align-items: center;
