@media (prefers-reduced-motion: reduce) { .ds-header-plan { transition: none !important; } }
.ds-header-plan {
    font-size: 12px;
    min-height: 44px;
    padding: 12px;
  }
.ds-header-plan svg {
    width: 18px;
    height: 18px;
  }
@media (prefers-reduced-motion: reduce) { .ds-nav a { transition: none !important; } }

.ds-chip-group { display: flex; gap: 8px; }
.ds-filter-chip { font-family: var(--body, Public,sans-serif); color: var(--ink, #253b30); cursor: pointer; transition: background .18s, color .18s; }
.ds-filter-chip {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  min-height: 44px;
  padding: 10px 17px;
  border: 1px solid var(--line, #d2d8cd);
  border-radius: 30px;
  background: transparent;
  font-size: 12px;
  font-weight: 500;
}
.ds-filter-chip svg {
  width: 17px;
  height: 17px;
}
.ds-filter-chip.ds-active {
  background: var(--pine, #234b39);
  border-color: var(--pine, #234b39);
  color: var(--white, #fffefa);
}
.ds-filter-chip:hover:not(.ds-active) {
  background: #e4e8dd;
}
.ds-filter-chip:focus-visible { outline: 3px solid var(--pine, #234b39); outline-offset: 5px; }
@media (prefers-reduced-motion: reduce) { .ds-filter-chip { animation: none !important; transition: none !important; } }

.ds-icon-button:hover {
  background: #e4e8dd;
}
.ds-icon-button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 5px;
  min-width: 44px;
  min-height: 44px;
  background: transparent;
  border-radius: 50%;
}
.ds-stay-card { font-family: var(--body, Public,sans-serif); color: var(--ink, #253b30); }
.ds-stay-card a { color: inherit; }
.ds-stay-card h3, .ds-stay-card p { margin: 0; }
.ds-stay-card p { line-height: 1.65; }
.ds-stay-card img { display: block; width: 100%; object-fit: cover; }
.ds-stay-card button { border: 0; cursor: pointer; transition: background .18s, color .18s; }
.ds-stay-card svg { width: 22px; height: 22px; flex-shrink: 0; }
.ds-stay-card {
  min-width: 0;
  position: relative;
}
.ds-stay-link {
  display: block;
  text-decoration: none;
  border-radius: 6px;
}
.ds-stay-photo {
  position: relative;
  overflow: hidden;
  aspect-ratio: 1.24;
  background: #d7ded0;
  border-radius: 6px;
}
.ds-stay-photo img {
  height: 100%;
  transition: transform .5s var(--ease, cubic-bezier(.16,1,.3,1));
}
.ds-stay-link:hover img {
  transform: scale(1.035);
}
.ds-stay-photo-label {
  position: absolute;
  bottom: 14px;
  left: 14px;
  padding: 7px 10px;
  background: var(--paper, #f6f5ef);
  font-size: 12px;
  font-weight: 500;
  border-radius: 2px;
}
.ds-favorite-button {
  position: absolute;
  top: 12px;
  right: 12px;
  background: var(--white, #fffefa);
  color: var(--pine, #234b39);
  z-index: 1;
  box-shadow: 0 3px 14px rgba(20, 40, 25, .12);
}
.ds-favorite-button[aria-pressed=true] svg {
  fill: var(--pine, #234b39);
}
.ds-stay-title-row {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 10px;
  margin-top: 18px;
}
.ds-stay-title-row h3 {
  font-size: 18px;
  font-weight: 600;
  letter-spacing: -.03em;
  line-height: 1.3;
}
.ds-stay-price {
  font-size: 16px;
  font-weight: 600;
  white-space: nowrap;
  font-variant-numeric: tabular-nums;
}
.ds-stay-price small {
  font-size: 12px;
  font-weight: 400;
}
.ds-stay-meta {
  display: flex;
  gap: 12px;
  align-items: center;
  margin-top: 9px;
  color: var(--muted, #56675b);
  font-size: 12px;
}
.ds-stay-meta span {
  display: flex;
  gap: 5px;
  align-items: center;
}
.ds-stay-meta svg {
  width: 14px;
  height: 14px;
}
.ds-stay-bottom {
  display: flex;
  align-items: center;
  justify-content: space-between;
  border-top: 1px solid var(--line, #d2d8cd);
  margin-top: 15px;
  padding-top: 12px;
  font-size: 12px;
  color: var(--muted, #56675b);
}
.ds-stay-bottom svg {
  width: 18px;
  height: 18px;
  color: var(--pine, #234b39);
}
.ds-stay-link:focus-visible { outline: 3px solid var(--pine, #234b39); outline-offset: 5px; }
.ds-favorite-button:focus-visible { outline: 3px solid var(--pine, #234b39); outline-offset: 5px; }
@media (prefers-reduced-motion: reduce) { .ds-stay-card button, .ds-stay-photo img { animation: none !important; transition: none !important; } }

.ds-sheet { background: var(--paper, #f6f5ef); color: var(--ink, #253b30); font-family: var(--body, Public,sans-serif); border-radius: 12px 0 0 12px; overflow: hidden; }
:where(.ds-sheet) h2, :where(.ds-sheet) p { margin: 0; }
.ds-sheet h2 { font-family: var(--display, Archivo,sans-serif); font-weight: 400; letter-spacing: -.035em; line-height: 1.07; text-wrap: balance; }
.ds-sheet p { line-height: 1.65; }
.ds-sheet :where(button) { font-family: var(--body, Public,sans-serif); color: inherit; border: 0; cursor: pointer; transition: background .18s, color .18s; }
.ds-sheet svg { width: 22px; height: 22px; flex-shrink: 0; }
.ds-dialog-top {
  position: sticky;
  top: 0;
  z-index: 2;
  background: var(--paper, #f6f5ef);
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 20px;
  padding: 24px 28px;
  border-bottom: 1px solid var(--line, #d2d8cd);
}
.ds-dialog-top h2 {
  font-size: 28px;
}
.ds-quote-breakdown {
  border-top: 1px solid #bcc6b5;
  padding-top: 16px;
  font-size: 12px;
}
.ds-quote-row {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  gap: 15px;
  line-height: 1.5;
  margin: 9px 0;
}
.ds-quote-row span:last-child {
  white-space: nowrap;
  font-variant-numeric: tabular-nums;
}
.ds-quote-row.ds-discount {
  color: #375c2b;
}
.ds-quote-row.ds-total {
  font-size: 18px;
  font-weight: 600;
  border-top: 1px solid #bcc6b5;
  margin-top: 16px;
  padding-top: 14px;
}
.ds-quote-note {
  font-size: 12px;
  color: var(--muted, #56675b);
  margin-top: 10px;
}
.ds-plan-demo-note {
  font-size: 12px;
  margin-top: 20px;
  background: var(--lime, #e5ed83);
  padding: 14px 16px;
  border-radius: 4px;
}
.ds-plan-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
  margin-top: 24px;
}
.ds-plan-actions .ds-button {
  font-size: 12px;
  flex: 1;
  gap: 10px;
  padding: 14px;
  min-width: 145px;
}
.ds-plan-secondary {
  display: flex;
  justify-content: space-between;
  gap: 20px;
  margin-top: 18px;
}
.ds-plan-secondary .ds-text-button {
  font-size: 12px;
}
.ds-button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 24px;
  min-height: 52px;
  padding: 15px 24px;
  text-decoration: none;
  font-size: 14px;
  font-weight: 600;
  border-radius: 4px;
  white-space: nowrap;
}
.ds-button-dark {
  background: var(--pine, #234b39);
  color: var(--white, #fffefa);
}
.ds-button-dark:hover {
  background: #143825;
}
.ds-button-outline {
  background: transparent;
  box-shadow: inset 0 0 0 1px var(--pine, #234b39);
}
.ds-button-outline:hover {
  background: #e9edde;
}
.ds-text-button {
  display: inline-flex;
  align-items: center;
  gap: 20px;
  min-height: 44px;
  padding: 8px 0;
  border-bottom: 1px solid currentColor;
  background: transparent;
  font-size: 14px;
  font-weight: 600;
  text-decoration: none;
}
.ds-text-button:hover {
  color: #52723a;
}
.ds-icon-button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 5px;
  min-width: 44px;
  min-height: 44px;
  background: transparent;
  border-radius: 50%;
}
.ds-icon-button:hover {
  background: #e4e8dd;
}
.ds-plan-content {
  padding: 28px;
}
.ds-sheet button:focus-visible { outline: 3px solid var(--pine, #234b39); outline-offset: 5px; }
@media (prefers-reduced-motion: reduce) { .ds-sheet :where(button) { animation: none !important; transition: none !important; } }
